    'admin_leader_operating_system.leader.opportunity_modal_empty' => 'Aktualisht nuk ka sinjale shtesë, por fokusi duhet të mbetet te CTA-të më të forta, konvertimi më i mirë dhe një rrugë më e qartë drejt regjistrimit ose blerjes.',
