    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.text' => 'Bashkëpunëtori ka gjithsej %s klikime, por vetëm %s%% prej tyre përfundojnë në faqet e dyqanit Forever ose te destinacionet e zbritjeve.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_1' => 'Vendose më lart në faqe butonin CTA të dyqanit online ose të zbritjes dhe përsërite pranë pjesës së poshtme të profilit ose postimit të blogut.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2' => 'Shto një thirrje për veprim më të qartë në kanalin kryesor të trafikut, në mënyrë që vizitorët të shkojnë te një destinacion Forever dhe jo vetëm te përmbajtja informuese.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2_source' => 'Për burimin %s, provo një CTA më të qartë që i çon përdoruesit drejtpërdrejt nga përmbajtja te dyqani online Forever ose te destinacioni i zbritjes.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_3' => 'Shqyrto nëse blloqet e blogut, shitjeve dhe zbritjeve e bëjnë rrugën e blerjes mjaftueshëm të dukshme dhe të përsëritur.',
