    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3' => 'Provo një rrugë më të thjeshtë drejt regjistrimit ose blerjes dhe hiq hapat ngatërrues pas klikimit të parë.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3_country' => 'Nëse pjesa më e madhe e trafikut vjen nga %s, kontrollo nëse faqja e synuar është lokalizuar saktë dhe hap versionin e duhur për tregun.',
