    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_1' => 'Mbaje burimin që po sjell rritje, por përmirëso tekstin e CTA-së dhe mesazhin hyrës që të përcaktohet më mirë synimi për të blerë.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_2' => 'Ndërto besim para CTA-së: përdor një dëshmi, rezultat, mini FAQ ose shpjegim të qartë se çfarë ndodh pas klikimit.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_3' => 'Krahaso burimet e klikimeve dhe vazhdo t\'u japësh përparësi vetëm kanaleve që sjellin regjistrime ose kontakte potenciale me cilësi më të lartë, jo thjesht volum trafiku.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.label' => 'Shfrytëzo interesin ekzistues për të krijuar një rrugë më të fortë drejt shitjes',
